define(['underscore','ko'],function(_,ko){'use strict';let paymentMethodData=ko.observable(null),email=ko.observable(null),shippingAddress=ko.observable(null);return{paymentMethodData:paymentMethodData,email:email,shippingAddress:shippingAddress,getPaymentMethodData:function(){return this.paymentMethodData();},setPaymentMethodData:function(value){this.paymentMethodData(_.isObject(value)?value:null);},getEmail:function(){return this.email();},setEmail:function(value){this.email(_.isString(value)?value:null);},getShippingAddress:function(){return shippingAddress();},setShippingAddress:function(value){this.shippingAddress(_.isObject(value)?value:null);},resetDefaultData:function(){this.setPaymentMethodData(null);this.setEmail(null);this.setShippingAddress(null);}};});